ALTER TABLE `tools_notification`
    MODIFY COLUMN `wechat_template_id` varchar(60) NOT NULL DEFAULT 0 COMMENT '模板消息ID' AFTER `wechat_status`,
    MODIFY COLUMN `wx_subscribe_template_id` varchar(60) NOT NULL DEFAULT 0 COMMENT '订阅消息ID' AFTER `wx_subscribe_status`,
    MODIFY COLUMN `sms_template_id` varchar(60) NOT NULL DEFAULT 0 COMMENT '短信ID' AFTER `sms_status`,
    MODIFY COLUMN `email_template_id` varchar(60) NOT NULL DEFAULT 0 COMMENT '邮件模板ID' AFTER `email_status`,
    MODIFY COLUMN `ding_template_id` varchar(60) NOT NULL DEFAULT 0 COMMENT '钉钉模板ID' AFTER `ding_status`,
    MODIFY COLUMN `wx_work_template_id` varchar(60) NOT NULL DEFAULT 0 COMMENT '企业微信模板ID' AFTER `wx_work_status`;

ALTER TABLE `client_user` ADD COLUMN `REGISTER_TIME` datetime NULL COMMENT '注册时间' AFTER `GROUP_ID`;

ALTER TABLE `tools_notification` ADD COLUMN `scene_params` varchar(500) NULL COMMENT '场景参数说明' AFTER `target_type`;





